<script setup lang="ts">
const route = useRoute(); const token = computed(() => typeof route.query.token === 'string' ? route.query.token : '')
const password = ref(''); const confirmation = ref(''); const error = ref(''); const success = ref(false); const pending = ref(false)
async function submit() { error.value = ''; if (!token.value) { error.value = 'Ссылка недействительна или устарела'; return } if (password.value !== confirmation.value) { error.value = 'Пароли не совпадают'; return } pending.value = true; try { await $fetch('/api/auth/set-password', { method: 'POST', body: { token: token.value, password: password.value } }); success.value = true } catch (cause: any) { error.value = cause?.data?.statusMessage ?? 'Не удалось установить пароль' } finally { pending.value = false } }
</script>
<template><div class="w-full max-w-md"><NuxtLink to="/login" class="brand-mark mb-10 text-2xl lg:hidden">aparts<span>.</span></NuxtLink><div class="surface p-6 sm:p-8"><template v-if="success"><div class="grid size-12 place-items-center rounded-2xl bg-[var(--color-primary-soft)] text-[var(--color-primary)]"><UIcon name="i-lucide-check" class="size-6" /></div><h2 class="mt-6 text-3xl font-semibold tracking-[-.045em]">Пароль установлен</h2><p class="mt-2 text-sm leading-6 text-[var(--color-muted)]">Аккаунт готов. Теперь можно войти в CRM.</p><UButton to="/login" block size="lg" class="mt-7">Перейти ко входу</UButton></template><template v-else><h2 class="text-3xl font-semibold tracking-[-.045em]">Создайте пароль</h2><p class="mt-2 text-sm leading-6 text-[var(--color-muted)]">Минимум 8 символов. Не используйте пароль от почты.</p><form class="mt-7 space-y-5" @submit.prevent="submit"><UFormField label="Новый пароль"><UInput v-model="password" type="password" autocomplete="new-password" class="w-full" minlength="8" required /></UFormField><UFormField label="Повторите пароль"><UInput v-model="confirmation" type="password" autocomplete="new-password" class="w-full" minlength="8" required /></UFormField><UAlert v-if="error" color="error" variant="soft" :description="error" /><UButton type="submit" block size="lg" :loading="pending">Сохранить пароль</UButton></form></template></div></div></template>
